using System; using System.Web.Mvc; using PAP.Generators; namespace PAP.Mvc.Controllers { public class AdminController:Controller { private readonly GeneratorCatalog _catalog=new GeneratorCatalog(); public ActionResult Index(){return View(_catalog.GetStatus());} [HttpPost,ValidateAntiForgeryToken] public ActionResult Generate(string entity){try{TempData["Mensaje"]=_catalog.Generate(entity);}catch(Exception ex){TempData["Error"]=ex.Message;} return RedirectToAction("Index");} } }